    if (!v.status.control || now - v.status.control.lastRxMs < 0 || now - v.status.control.lastRxMs > CFG.CONTROL_MAX_AGE_MS)
        return "VESC-Steuerungsstatus fehlt: LispBM aktualisieren / Verbindung pruefen";
    return "";
}

function pid(dt) {
    if (s.targetKn === 0) {
        s.integral = 0;
        s.pTerm = 0;
        s.dTerm = 0;
        s.errorKn = 0;
        s.unclampedPercent = 0;
        command(0, true, true);
        s.reason = "PID aktiv, Sollwert 0 kn";
        return;
    }
    const problem = motorProblem() || sogProblem();
    if (problem) { cancel(problem, true); return; }
    const error = s.targetKn - s.filteredKn;
    const p = s.pid.kp * error;
    // D nur aus Messwertaenderungen, damit Sollwertspruenge keinen D-Stoss erzeugen.
    const d = -s.pid.kd * s.derivativeKnS;
    const beforeIntegration = p + s.integral + d;
    // Klassisches Clamping-Anti-Windup an den tatsaechlichen Ausgangsgrenzen.
    // Bei Saettigung nur integrieren, wenn der Fehler die Saettigung abbaut.
    if (!((beforeIntegration >= CFG.MAX_PERCENT && error > 0) ||
          (beforeIntegration <= 0 && error < 0))) {
        s.integral = clamp(s.integral + s.pid.ki * error * dt,
                           -CFG.MAX_PERCENT, CFG.MAX_PERCENT);
    }
    s.errorKn = error;
    s.pTerm = p;
    s.dTerm = d;
    s.unclampedPercent = p + s.integral + d;
    // Keine Stellwertrampe: grosse positive Abweichung saettigt direkt auf 100 %.
    command(clamp(s.unclampedPercent, 0, CFG.MAX_PERCENT), true);
    s.reason = "PID aktiv";
}

// Ein zuvor aktiver Tempomat wird nach Redeploy beendet, niemals wieder aktiviert.
if (s.pendingStop) {
    s.pendingStop = false;
    cancel("Nach Deploy ausgeschaltet", true);
}
if (!s.pidUiPublished) tuningUi = tuningReply(true, "Aktive Reglerparameter geladen");

switch (msg.topic) {
case "cruise_pid_config": {
    const values = msg.payload;
    let invalid = "";
    for (const key of ["kp", "ki", "kd"]) {
        const value = values && typeof values === "object" && !Array.isArray(values) ? values[key] : undefined;
        if (!numeric(value) || value < 0 || value > PID_LIMITS[key]) {
            invalid = `${key.toUpperCase()} muss eine Zahl von 0 bis ${PID_LIMITS[key]} sein`;
            break;
        }
    }
    if (invalid) {
        tuningUi = tuningReply(false, invalid, msg.requestId);
        break;
    }
    const windowSize = Object.prototype.hasOwnProperty.call(values, "sogWindowSize")
        ? values.sogWindowSize : s.sogWindowSize;
    if (!Number.isInteger(windowSize) || windowSize < 1 || windowSize > CFG.SOG_WINDOW_MAX) {
        tuningUi = tuningReply(false, `SOG-Mittelwert muss eine ganze Zahl von 1 bis ${CFG.SOG_WINDOW_MAX} sein`, msg.requestId);
        break;
    }
    const next = {kp: values.kp, ki: values.ki, kd: values.kd};
    try {
        flow.set("vescCruiseConfig", {...savedConfig(), targetKn: s.targetKn, pid: {...next}, sogWindowSize: windowSize}, "file");
    } catch (error) {
        tuningUi = tuningReply(false, "Speichern fehlgeschlagen: " + error.message, msg.requestId);
        break;
    }
    s.pid = next;
    if (windowSize !== s.sogWindowSize) {
        s.sogWindowSize = windowSize;
        s.sogSamplesKn = s.sogSamplesKn.slice(-windowSize);
        updateSogMean();
        // Ein geaendertes Fenster ist keine gemessene Beschleunigung.
        s.derivativeKnS = 0;
    }
    // I bleibt erhalten; bei reiner Gain-Aenderung auch D. Kein Acquire.
    if (s.enabled) {
        const elapsed = now - s.lastTickMs;
        if (elapsed < 0 || elapsed > CFG.MAX_TICK_GAP_MS) cancel("Regeltakt unterbrochen", true);
        else pid(0);
    }
    tuningUi = tuningReply(true, "Reglerparameter übernommen und gespeichert", msg.requestId);
    break;
}
case "navigation.speedOverGround": {
    if (msg.context !== "vessels.self") { if (drive) break; return null; }
    const stamp = typeof msg.timestamp === "string" ? Date.parse(msg.timestamp) : NaN;
    if (!numeric(msg.payload) || msg.payload < 0 || msg.payload > CFG.SOG_MAX_M_S || !Number.isFinite(stamp) ||
        now - stamp > CFG.SOG_MAX_AGE_MS || stamp - now > CFG.FUTURE_TOLERANCE_MS) {
        s.sogKn = null;
        resetSogWindow();
        if (s.enabled) cancel("SOG ungueltig/veraltet", true);
        else s.reason = "SOG ungueltig/veraltet";
        break;
    }
    // Gleiche/aeltere Zeitstempel sind kein neues GPS-Sample.
    if (numeric(s.sogTimestampMs) && stamp <= s.sogTimestampMs) break;
    const kn = msg.payload * 3600 / 1852;
    if (!Number.isFinite(kn)) {
        s.sogKn = null;
        resetSogWindow();
        if (s.enabled) cancel("SOG ungueltig", true);
        break;
    }
    const sampleDt = numeric(s.sogTimestampMs) ? (stamp - s.sogTimestampMs) / 1000 : 0;
    const receiveGap = now - s.sogReceivedMs;
    const reset = !numeric(s.filteredKn) || sampleDt <= 0 ||
        sampleDt > CFG.SOG_MAX_AGE_MS / 1000 || receiveGap < 0 || receiveGap > CFG.SOG_MAX_AGE_MS;
    const previousFiltered = s.filteredKn;
    if (reset) resetSogWindow();
    s.sogSamplesKn.push(kn);
    if (s.sogSamplesKn.length > s.sogWindowSize) s.sogSamplesKn.shift();
    updateSogMean();
    if (!reset) {
        const measuredDerivative = (s.filteredKn - previousFiltered) / sampleDt;
        const dAlpha = 1 - Math.exp(-sampleDt / CFG.D_FILTER_TAU_S);
        s.derivativeKnS += dAlpha * (measuredDerivative - s.derivativeKnS);
    }
    s.sogKn = kn;
    s.sogTimestampMs = stamp;
    s.sogReceivedMs = now;
    break;
}
case "cruise_setpoint": {
    if (!numeric(msg.payload) || msg.payload < 0 || msg.payload > 4) {
        node.error("Tempomat-Sollwert muss eine Zahl von 0 bis 4 kn sein", msg);
        slider = {payload: s.targetKn};
        break;
    }
    const target = Math.round(msg.payload * 10) / 10;
    try {
        flow.set("vescCruiseConfig", {...savedConfig(), targetKn: target, pid: {...s.pid}, sogWindowSize: s.sogWindowSize}, "file");
    } catch (error) {
        node.error("Sollwert konnte nicht gespeichert werden: " + error.message, msg);
        slider = {payload: s.targetKn};
        break;
    }
    s.targetKn = target;
    if (s.enabled) {
        const elapsed = now - s.lastTickMs;
        if (elapsed < 0 || elapsed > CFG.MAX_TICK_GAP_MS) cancel("Regeltakt unterbrochen", true);
        else pid(0); // P wirkt sofort; Zeit fuer I ausschliesslich im Regeltakt.
    }
    break;
}
case "cruise_toggle": {
    if (s.enabled) {
        cancel("Tempomat ausgeschaltet", true);
        break;
    }
    const problem = motorProblem() || sogProblem();
    const last = flow.get("vescLastCommand", "memory");
    if (problem || (numeric(last?.percent) && last.percent < 0)) {
        s.reason = problem || "Erst manuell auf 0 %, dann Tempomat";
        break;
    }
    s.enabled = true;
    s.derivativeKnS = 0;
    s.integral = 0; // P beim Einschalten nicht mehr durch den Integrator aufheben.
    s.lastTickMs = now;
    s.acquireNext = true;
    pid(0);
    break;
}
case "cruise_manual": {
    if (msg._cruiseUi === true) { if (drive) break; return null; }
    if (!numeric(msg.payload) || msg.payload < -100 || msg.payload > 100) { if (drive) break; return null; }
    cancel(msg.payload === 0 ? "STOP / Handbetrieb 0 %" : "Handbetrieb", false);
    if (msg.payload === 0) command(0, false, true);
    else if (v.config?.engineOn === true && !motorProblem()) command(msg.payload, false);
    else s.reason = v.config?.engineOn === true ? motorProblem() : "Motor ausgeschaltet";
    break;
}
case "cruise_stop":
    cancel("STOP", true);
    break;
case "cruise_engine_off":
    cancel("Motor ausgeschaltet", true);
    break;
case "cruise_init":
    slider = {payload: s.targetKn};
    tuningUi = tuningReply(true, "Aktive Reglerparameter geladen");
    break;
case "vesc_control_feedback": {
    const feedback = v.status.control;
    if (s.enabled && feedback?.source === 0) {
        // Poti hat physisch uebernommen: keine STOP-Anforderung dagegen senden.
        cancel("Poti hat uebernommen", false);
        s.outputPercent = feedback.percent;
        manualUi = {payload: feedback.percent, _cruiseUi: true};
    }
    if (!s.enabled && numeric(feedback?.percent))
        manualUi = {payload: feedback.percent, _cruiseUi: true};
    break;
}
case "cruise_tick": {
    if (!s.enabled) break;
    const problem = motorProblem() || sogProblem();
    if (problem) { cancel(problem, true); break; }
    const elapsed = now - s.lastTickMs;
    if (elapsed < 0 || elapsed > CFG.MAX_TICK_GAP_MS) {
        cancel("Regeltakt unterbrochen", true);
        break;
    }
    if (elapsed === 0) break;
    s.lastTickMs = now;
    pid(elapsed / 1000);
    break;
}
default:
    if (drive) break;
    return null;
}

if (tuningUi) s.pidUiPublished = true;
flow.set("vescCruise", s, "memory");
const fresh = !sogProblem();
const text = `${s.enabled ? "EIN" : "AUS"} | Soll ${s.targetKn.toFixed(1)} kn | SOG Ø ${fresh ? s.filteredKn.toFixed(2) : "--"} kn (roh ${fresh ? s.sogKn.toFixed(2) : "--"}; ${s.sogSamplesKn.length}/${s.sogWindowSize} Werte) | Sollwert ${s.outputPercent.toFixed(1)} % | P ${s.pTerm.toFixed(1)} / I ${s.integral.toFixed(1)} / D ${s.dTerm.toFixed(1)} | ${s.reason}`;
node.status({fill: s.enabled ? "green" : "grey", shape: s.enabled ? "dot" : "ring", text});
return [drive, {payload: s.enabled, label: s.enabled ? "Tempomat: EIN" : "Tempomat: AUS", background: s.enabled ? "#2e7d32" : "#616161"}, slider, {payload: text}, manualUi, tuningUi];

initialize:
const saved = flow.get("vescCruiseConfig", "file");
const targetKn = typeof saved?.targetKn === "number" && Number.isFinite(saved.targetKn) && saved.targetKn >= 0 && saved.targetKn <= 4 ? saved.targetKn : 0;
const sogWindowSize = Number.isInteger(saved?.sogWindowSize) && saved.sogWindowSize >= 1 && saved.sogWindowSize <= 100 ? saved.sogWindowSize : 10;
function gain(key, fallback, maximum) {
    const value = saved?.pid?.[key];
    return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= maximum ? value : fallback;
}
flow.set("vescCruise", {
    enabled: false,
    acquireNext: false,
    targetKn,
    sogWindowSize,
    sogSamplesKn: [],
    pid: {kp: gain("kp", 100, 10000), ki: gain("ki", 5, 1000), kd: gain("kd", 10, 10000)},
    pidUiPublished: false,
    integral: 0,
    pTerm: 0,
    dTerm: 0,
    errorKn: 0,
    unclampedPercent: 0,
    derivativeKnS: 0,
    outputPercent: 0,
    lastTickMs: 0,
    sogKn: null,
    filteredKn: null,
    sogTimestampMs: null,
    sogReceivedMs: 0,
    serial: 0,
    session: `${Date.now()}-${Math.random()}`,
    pendingStop: true,
    reason: "Bereit; Tempomat ausgeschaltet"
}, "memory");
